import java.util.*

class CoffeeMachine {

    var water = 0
    var milk = 0
    var beans = 0

    private var scanner = Scanner(System.`in`)

    enum class Coffee(val coffeeName: String, val water: Int, val milk: Int, val beans: Int) {
        ESPRESSO("эспрессо", 60, 0, 10),
        AMERICANO("американо", 120, 0, 10),
        CAPPUCCINO("капучино", 120, 60, 20),
        LATTE("латте", 240, 120, 20)
    }

    fun start() {
        println("Кофемашина готова к работе")
        do {
            println("Введите команду")
            if (!scanner.hasNextLine()) {
                return
            }
            val command = scanner.nextLine()
            when (command.lowercase()) {
                "выключить" -> {
                    println("До свидания!")
                    return
                }
                "наполнить" -> refill()
                "статус" -> printStatus()
                "кофе" -> coffeeMenu()
            }
        } while (true)
    }

    // Меню выбора напитка
    private fun coffeeMenu() {
        println("""Введите название напитка или "назад" для возврата в главное меню""")
        if (!scanner.hasNextLine()) {
            return
        }
        val name = scanner.nextLine()
        if (name.equals("назад", ignoreCase = true)) {
            return
        }
        val coffee = Coffee.values().firstOrNull {
            it.coffeeName.equals(name, ignoreCase = true) || it.name.equals(name, ignoreCase = true)
        }
        if (coffee == null) {
            println("Рецепт не найден!")
            return
        }
        makeCoffee(coffee)
    }

    // Приготовление напитка по выбранному рецепту
    private fun makeCoffee(coffee: Coffee) {
        if (!isIngredientsEnough(coffee)) {
            return
        }
        water -= coffee.water
        milk -= coffee.milk
        beans -= coffee.beans
        println("${coffee.coffeeName} готов")
    }

    // Пополнение ингредиентов до максимума
    private fun refill() {
        water = 2000
        milk = 1000
        beans = 500
        println("Ингредиенты пополнены")
    }

    // Вывод текущего состояния кофемашины
    private fun printStatus() {
        println("Ингредиентов осталось:")
        println("$water мл воды")
        println("$milk мл молока")
        println("$beans гр кофе")
    }

    // Проверка, хватает ли ингредиентов для приготовления напитка
    private fun isIngredientsEnough(coffee: Coffee): Boolean {
        if (water < coffee.water) {
            println("Недостаточно воды!")
            return false
        }
        if (milk < coffee.milk) {
            println("Недостаточно молока!")
            return false
        }
        if (beans < coffee.beans) {
            println("Недостаточно кофе!")
            return false
        }
        return true
    }
}

